// Une méthode qui renvoie null quand elle ne trouve rien.
static String chercherEmail(String nom) {
    if (nom.equals("ana")) {
        return "ana@example.com";
    }
    return null; // personne trouvé : on renvoie null
}

public class Demo {
    public static void main(String[] args) {
        String email = chercherEmail("bob"); // email vaut null

        // On croit avoir un email, on appelle une méthode dessus...
        System.out.println(email.toUpperCase());
        // BOUM : NullPointerException, car email est null.
    }
}

import java.util.Optional;

public class Demo {
    public static void main(String[] args) {
        // 1) Optional.of : une valeur présente, garantie NON nulle.
        Optional<String> plein = Optional.of("ana@example.com");

        // 2) Optional.empty : une boite volontairement vide.
        Optional<String> vide = Optional.empty();

        // 3) Optional.ofNullable : valeur peut-être nulle.
        //    Si l'argument est null -> boite vide ; sinon -> boite pleine.
        String peutEtreNull = trouverNom(); // peut renvoyer null
        Optional<String> prudent = Optional.ofNullable(peutEtreNull);
    }

    static String trouverNom() { return null; }
}

import java.util.Optional;

// AVANT : renvoie null quand on ne trouve rien (dangereux).
static String chercherEmailAncien(String nom) {
    if (nom.equals("ana")) return "ana@example.com";
    return null;
}

// APRÈS : renvoie un Optional, l'absence est visible dans le type.
static Optional<String> chercherEmail(String nom) {
    if (nom.equals("ana")) {
        return Optional.of("ana@example.com");
    }
    return Optional.empty(); // on dit clairement "rien trouvé"
}

import java.util.Optional;

public class Demo {
    public static void main(String[] args) {
        Optional<String> email = Optional.of("Ana@Example.com");

        // On transforme la valeur SI elle est présente : minuscules puis longueur.
        Optional<String> minuscule = email.map(e -> e.toLowerCase());
        Optional<Integer> longueur = email.map(e -> e.length());

        System.out.println(minuscule); // Optional[ana@example.com]
        System.out.println(longueur);  // Optional[15]

        // Sur une boite vide, map ne fait rien et ne plante pas.
        Optional<String> rien = Optional.empty();
        System.out.println(rien.map(e -> e.toUpperCase())); // Optional.empty
    }
}

import java.util.Optional;

// Cette méthode renvoie DÉJÀ un Optional.
static Optional<String> domaine(String email) {
    int i = email.indexOf('@');
    if (i < 0) return Optional.empty();
    return Optional.of(email.substring(i + 1));
}

public class Demo {
    public static void main(String[] args) {
        Optional<String> email = Optional.of("ana@example.com");

        // Avec map : boite dans une boite, difficile à utiliser.
        Optional<Optional<String>> emboite = email.map(e -> domaine(e));

        // Avec flatMap : une seule boite, propre.
        Optional<String> aplati = email.flatMap(e -> domaine(e));
        System.out.println(aplati); // Optional[example.com]
    }
}

import java.util.Optional;

public class Demo {
    public static void main(String[] args) {
        Optional<String> email = Optional.of("ana@example.com");

        // On garde l'email seulement s'il contient un @.
        Optional<String> valide = email.filter(e -> e.contains("@"));
        System.out.println(valide); // Optional[ana@example.com]

        // Une valeur qui échoue au test donne une boite vide.
        Optional<String> sansArobase = Optional.of("ana.example.com");
        System.out.println(sansArobase.filter(e -> e.contains("@"))); // Optional.empty

        // On enchaine : filtrer puis transformer, toujours sans NPE.
        Optional<Integer> longueur = email
            .filter(e -> e.contains("@"))
            .map(e -> e.length());
        System.out.println(longueur); // Optional[15]
    }
}

import java.util.Optional;

public class Demo {
    public static void main(String[] args) {
        Optional<String> trouve = Optional.of("ana@example.com");
        Optional<String> vide = Optional.empty();

        // orElse : renvoie la valeur, ou l'argument par défaut si vide.
        System.out.println(trouve.orElse("inconnu")); // ana@example.com
        System.out.println(vide.orElse("inconnu"));   // inconnu

        // orElseGet : pareil, mais le défaut est calculé SEULEMENT si vide.
        // Utile quand produire le défaut coute cher (appel, calcul).
        String valeur = vide.orElseGet(() -> genererDefautCouteux());
        System.out.println(valeur); // defaut-calcule
    }

    static String genererDefautCouteux() {
        return "defaut-calcule";
    }
}

import java.util.Optional;

public class Demo {
    public static void main(String[] args) {
        Optional<String> vide = Optional.empty();

        // orElseThrow : si présent, renvoie la valeur ;
        // si vide, lève une exception que TU choisis, avec un message clair.
        try {
            String email = vide.orElseThrow(
                () -> new IllegalStateException("email introuvable"));
            System.out.println(email);
        } catch (IllegalStateException e) {
            System.out.println("Erreur : " + e.getMessage());
        }

        // Sans argument, orElseThrow() lève NoSuchElementException.
        // Mieux que get() car le nom dit clairement "ça peut échouer".
    }
}

import java.util.Optional;

public class Demo {
    public static void main(String[] args) {
        Optional<String> trouve = Optional.of("ana@example.com");
        Optional<String> vide = Optional.empty();

        // ifPresent : exécute l'action SEULEMENT si une valeur est là.
        trouve.ifPresent(e -> System.out.println("Envoi vers " + e));
        vide.ifPresent(e -> System.out.println("jamais affiché"));

        // ifPresentOrElse : une action si présent, une autre si vide.
        vide.ifPresentOrElse(
            e -> System.out.println("Envoi vers " + e),
            () -> System.out.println("Aucun email : rien à envoyer"));
    }
}

